const {chromium}=require('playwright'),fs=require('node:fs');
(async()=>{const b=await chromium.launch({channel:'chrome'}),rows=[];try{for(const [name,version,port]of [['rocket-launch','before',8393],['rocket-launch','after',8391],['solar-lunar-eclipses','before',8393],['solar-lunar-eclipses','after',8392]]){
const p=await b.newPage({viewport:{width:1600,height:900}}),errors=[];p.on('pageerror',e=>errors.push(e.message));await p.goto(`http://127.0.0.1:${port}/experiments/${name}/`);if(name==='rocket-launch'){await p.locator('#chapters>button').nth(2).click();await p.locator('#steps button').filter({hasText:'为什么要分级'}).click();await p.waitForFunction(()=>!!RocketChapter3.adapter.stagingRig);if(version==='before')await p.locator('#dv-tab-2').click();await p.locator('#dv-play').click();}else if(version==='before'){await p.locator('#moon').fill('180');await p.locator('#enter').click();await p.locator('#observationOptions summary').click();await p.locator('#referenceCase').selectOption('total');await p.locator('#play').click();}else await p.locator('#continuousPlay').click();
await p.waitForTimeout(300);const sample=await p.evaluate(()=>new Promise(resolve=>{const frames=[],long=[],start=performance.now();let previous=start;const observer=new PerformanceObserver(list=>long.push(...list.getEntries().map(e=>e.duration)));observer.observe({type:'longtask'});function tick(t){frames.push(t-previous);previous=t;if(t-start<3000)requestAnimationFrame(tick);else{observer.disconnect();resolve({frames,long,userAgent:navigator.userAgent,dpr:devicePixelRatio,focused:document.hasFocus(),visibility:document.visibilityState});}}requestAnimationFrame(tick);}));rows.push({name,version,...sample,errors});await p.close();}fs.writeFileSync(__dirname+'/docs/review-20261115/performance-before-after.json',JSON.stringify(rows,null,2));console.log(rows.map(r=>({name:r.name,version:r.version,frames:r.frames.length,long:r.long.length,errors:r.errors})));}finally{await b.close();}})().catch(e=>{console.error(e);process.exitCode=1;});
